block.template:
{# Beispiel 5 · Ansprechpartner: Telefon über tel, E-Mail über mailto, Seite über ein Linkfeld. #}
<article class="person">
  {% if bild %}<div class="person__img">{{ bild | image('(min-width: 40rem) 10rem, 7rem', '1:1') }}</div>{% endif %}
  <div class="person__body">
    <h2 class="person__name">{{ name }}</h2>
    {% if funktion %}<p class="person__role">{{ funktion }}</p>{% endif %}
    {% if telefon or email %}
    <ul class="person__contact" role="list">
      {% if telefon %}<li><a href="{{ telefon | tel }}"><span class="person__ico" aria-hidden="true">{{ 'phone' | icon }}</span><span class="vh">{{ 'Telefon' | lt }}: </span>{{ telefon }}</a></li>{% endif %}
      {% if email %}<li><a href="{{ email | mailto }}"><span class="person__ico" aria-hidden="true">{{ 'envelope-simple' | icon }}</span><span class="vh">{{ 'E-Mail' | lt }}: </span>{{ email }}</a></li>{% endif %}
    </ul>
    {% endif %}
    {% if seite %}<p class="person__more"><a href="{{ seite }}">{{ linktext | default('Mehr erfahren') }}<span aria-hidden="true">{{ 'arrow-right' | icon }}</span></a></p>{% endif %}
  </div>
</article>

block.css:
.person {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1.25rem 1.75rem;
  max-width: 44rem;
  padding: clamp(1.25rem, 3vw, 2rem);
  border: 1px solid var(--cb-line);
  border-radius: var(--cb-radius);
  background: var(--cb-surface);
}
.person__img { flex: none; width: 7rem; }
.person__img img { display: block; width: 100%; height: auto; aspect-ratio: 1; object-fit: cover; border-radius: 50%; }
.person__body { flex: 1 1 16rem; min-width: 0; }
.person__name { margin: 0; font-size: 1.4rem; }
.person__role { margin: .2rem 0 0; color: var(--cb-muted); }
.person__contact { display: grid; gap: .5rem; margin: 1rem 0 0; padding: 0; list-style: none; }
.person__contact a { display: inline-flex; align-items: center; gap: .6rem; overflow-wrap: anywhere; }
.person__ico {
  display: inline-grid;
  place-items: center;
  flex: none;
  width: 2rem;
  height: 2rem;
  border-radius: 50%;
  background: color-mix(in srgb, var(--cb-accent) 15%, transparent);
}
.person__more { margin: 1rem 0 0; }
.person__more a { display: inline-flex; align-items: center; gap: .4rem; font-weight: 600; }
@media (min-width: 40rem) {
  .person__img { width: 10rem; }
}
.vh { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
